create table auditoria (id_entidad integer, fecha_hora datetime(6) not null, id_auditoria bigint not null auto_increment, ip_origen varchar(45), usuario_rol varchar(50), entidad varchar(60) not null, usuario_email varchar(100) not null, descripcion varchar(500), accion enum ('ACTUALIZAR','APROBAR','CREAR','ELIMINAR','LOGIN','LOGOUT','REGISTRO','RESET_PASSWORD') not null, primary key (id_auditoria)) engine=InnoDB;
create table cliente (id_cliente integer not null auto_increment, id_vendedor integer not null, fecha_registro datetime(6) not null, num_documento varchar(15) not null, correo varchar(100), telefono varchar(100), apellidos varchar(120), nombres varchar(120) not null, direccion varchar(200), tipo_documento enum ('CE','DNI','OTRO','RUC') not null, primary key (id_cliente)) engine=InnoDB;
create table comision (cantidad_cuotas integer not null, fecha_inicio_cuotas date not null, id_comision integer not null auto_increment, id_empresa integer not null, id_lote integer not null, id_vendedor integer not null, id_venta integer not null, monto_anticipo decimal(14,2) not null, monto_cuota decimal(14,2) not null, monto_pagado decimal(14,2) not null, monto_saldo decimal(14,2) not null, monto_total decimal(14,2) not null, porcentaje_aplicado decimal(5,4), fecha_registro datetime(6) not null, estado enum ('ANULADA','PAGADA','PAGADA_PARCIAL','PENDIENTE') not null, primary key (id_comision)) engine=InnoDB;
create table comprobante (aplica_detraccion bit not null, fecha_emision date not null, id_comprobante integer not null auto_increment, id_empresa integer not null, id_vendedor integer not null, igv decimal(14,2) not null, monto_detraccion decimal(14,2), porcentaje_igv decimal(5,2) not null, subtotal decimal(14,2) not null, total decimal(14,2) not null, fecha_registro datetime(6) not null, correlativo varchar(20), serie varchar(20), id_api_sunat varchar(40), concepto varchar(300) not null, estado enum ('ACEPTADO','ANULADO','EMITIDO','EN_PROCESO','RECHAZADO') not null, tipo enum ('BOLETA','FACTURA','NOTA_CREDITO','NOTA_DEBITO') not null, primary key (id_comprobante)) engine=InnoDB;
create table comprobante_pago (id_comprobante integer not null, id_comprobante_pago integer not null auto_increment, id_pago integer not null, id_vendedor integer not null, monto_aplicado decimal(14,2) not null, primary key (id_comprobante_pago)) engine=InnoDB;
create table detalle_comprobante (cantidad decimal(10,2) not null, id_comprobante integer not null, id_detalle integer not null auto_increment, id_vendedor integer not null, monto decimal(14,2) not null, descripcion varchar(200) not null, primary key (id_detalle)) engine=InnoDB;
create table empresa (id_empresa integer not null auto_increment, id_vendedor integer not null, fecha_registro datetime(6) not null, ruc varchar(11) not null, departamento varchar(60), distrito varchar(60), provincia varchar(60), correo varchar(100), telefono varchar(100), nombre_comercial varchar(120), razon_social varchar(150) not null, direccion varchar(200), cuentas_bancarias TEXT, primary key (id_empresa)) engine=InnoDB;
create table integracion_sunat (aplica_detraccion bit not null, cod_bien_detraccion varchar(4) not null, cod_medio_pago varchar(4) not null, id_integracion integer not null auto_increment, id_vendedor integer not null, porcentaje_detraccion decimal(5,2) not null, serie_factura varchar(4) not null, umbral_detraccion decimal(14,2) not null, fecha_actualizacion datetime(6), cta_banco varchar(25), api_url varchar(150), api_key varchar(512), api_secret varchar(512), primary key (id_integracion)) engine=InnoDB;
create table lote (area_m2 decimal(10,2), fecha_vence_separacion date, id_empresa integer not null, id_lote integer not null auto_increment, id_proyecto integer, id_vendedor integer not null, inicial decimal(14,2), monto_separacion decimal(10,2), num_cuotas integer, precio decimal(14,2) not null, precio_m2 decimal(10,2), saldo decimal(14,2), separacion_ajena bit not null, fecha_registro datetime(6) not null, manzana varchar(10) not null, numero varchar(10) not null, proyecto varchar(120) not null, descripcion varchar(150), motivo_estado varchar(300), estado enum ('DISPONIBLE','RESERVADO','VENDIDO') not null, primary key (id_lote)) engine=InnoDB;
create table pago_comision (fecha_pago date, fecha_programada date not null, id_comision integer not null, id_pago integer not null auto_increment, id_vendedor integer not null, monto decimal(14,2) not null, numero_cuota integer, fecha_registro datetime(6) not null, referencia varchar(60), notas varchar(200), estado enum ('ANULADO','PAGADO','PENDIENTE') not null, forma_pago enum ('DEPOSITO','EFECTIVO','OTRO','PLIN','TRANSFERENCIA','YAPE'), tipo enum ('AJUSTE','ANTICIPO','CUOTA','TOTAL') not null, primary key (id_pago)) engine=InnoDB;
create table parametro_comision (anticipo_monto_fijo decimal(14,2), anticipo_porcentaje decimal(5,4) not null, fecha_fin_vigencia date, fecha_inicio_vigencia date not null, id_empresa integer, id_parametro integer not null auto_increment, id_vendedor integer not null, meses_espera integer not null, monto_cuota decimal(14,2) not null, porcentaje_comision decimal(5,4) not null, porcentaje_comision_contado decimal(5,4) not null, fecha_registro datetime(6) not null, primary key (id_parametro)) engine=InnoDB;
create table proforma (id_cliente integer not null, id_empresa integer not null, id_proforma integer not null auto_increment, id_vendedor integer not null, total decimal(14,2), fecha datetime(6) not null, numero varchar(20) not null, observaciones varchar(500), estado enum ('ACEPTADA','ANULADA','EMITIDA') not null, primary key (id_proforma)) engine=InnoDB;
create table proforma_detalle (area_m2 decimal(10,2), id_lote integer, id_proforma integer not null, id_proforma_detalle integer not null auto_increment, precio_unitario decimal(14,2) not null, descripcion varchar(200) not null, primary key (id_proforma_detalle)) engine=InnoDB;
create table proyecto (id_empresa integer not null, id_proyecto integer not null auto_increment, id_vendedor integer not null, latitud decimal(10,8), longitud decimal(11,8), fecha_registro datetime(6) not null, nombre varchar(120) not null, ubicacion varchar(200), plano_ruta varchar(255), estado enum ('ACTIVO','INACTIVO') not null, primary key (id_proyecto)) engine=InnoDB;
create table refresh_token (id_usuario integer not null, revoked bit not null, expiryDate datetime(6) not null, id bigint not null auto_increment, token varchar(500) not null, primary key (id)) engine=InnoDB;
create table secuencia (anio integer not null, id_empresa integer not null, id_secuencia integer not null auto_increment, ultimo_numero integer not null, primary key (id_secuencia)) engine=InnoDB;
create table sesion_activa (activa bit not null, id_usuario integer not null, fechaLogueo datetime(6) not null, id bigint not null auto_increment, ultimoRefresh datetime(6) not null, ip varchar(50), user_agent varchar(500), primary key (id)) engine=InnoDB;
create table usuario (id_usuario integer not null auto_increment, dni varchar(8), fecha_registro datetime(6) not null, nombres varchar(80) not null, apellidos varchar(100) not null, contrasena varchar(100) not null, correo varchar(100) not null, telefono varchar(100), estado enum ('activo','inactivo','pendiente') not null, rol enum ('ADMINISTRADOR','VENDEDOR') not null, primary key (id_usuario)) engine=InnoDB;
create table vendedor_empresa (id_empresa integer not null, id_vendedor integer not null, id_vendedor_empresa integer not null auto_increment, fecha_registro datetime(6) not null, primary key (id_vendedor_empresa)) engine=InnoDB;
create table venta (comision_manual decimal(14,2), fecha_inicio_cuotas date, fecha_venta date not null, id_empresa integer not null, id_vendedor integer not null, id_venta integer not null auto_increment, monto_inicial decimal(14,2) not null, precio_venta decimal(14,2) not null, fecha_registro datetime(6) not null, notas varchar(300), estado enum ('ACTIVA','ANULADA') not null, modalidad enum ('CONTADO','FINANCIADO') not null, primary key (id_venta)) engine=InnoDB;
create table venta_cliente (id_cliente integer not null, id_venta integer not null, id_venta_cliente integer not null auto_increment, primary key (id_venta_cliente)) engine=InnoDB;
create table venta_lote (id_lote integer not null, id_venta integer not null, id_venta_lote integer not null auto_increment, primary key (id_venta_lote)) engine=InnoDB;
create index idx_auditoria_fecha on auditoria (fecha_hora);
create index idx_auditoria_usuario on auditoria (usuario_email);
create index idx_cliente_tenant on cliente (id_vendedor);
alter table cliente add constraint uk_cliente_tenant_doc unique (id_vendedor, num_documento);
create index idx_comision_tenant on comision (id_vendedor);
create index idx_comision_tenant_venta on comision (id_vendedor, id_venta);
create index idx_comprobante_tenant on comprobante (id_vendedor);
create index idx_comprobante_tenant_empresa on comprobante (id_vendedor, id_empresa);
create index idx_comp_pago_tenant on comprobante_pago (id_vendedor);
alter table comprobante_pago add constraint uk_comp_pago unique (id_comprobante, id_pago);
create index idx_detalle_tenant on detalle_comprobante (id_vendedor);
create index idx_empresa_tenant on empresa (id_vendedor);
alter table empresa add constraint uk_empresa_tenant_ruc unique (id_vendedor, ruc);
create index idx_integracion_tenant on integracion_sunat (id_vendedor);
alter table integracion_sunat add constraint uk_integracion_tenant unique (id_vendedor);
create index idx_lote_tenant on lote (id_vendedor);
alter table lote add constraint uk_lote_tenant unique (id_vendedor, id_empresa, proyecto, manzana, numero);
create index idx_pago_tenant on pago_comision (id_vendedor);
create index idx_pago_tenant_comision on pago_comision (id_vendedor, id_comision);
create index idx_param_tenant on parametro_comision (id_vendedor);
alter table proforma add constraint uk_proforma_numero unique (id_vendedor, numero);
create index idx_proyecto_v on proyecto (id_vendedor);
alter table proyecto add constraint uk_proyecto unique (id_vendedor, id_empresa, nombre);
