alter table secuencia add constraint uk_secuencia_empresa_anio unique (id_empresa, anio);
alter table usuario add constraint UK2mlfr087gb1ce55f2j87o74t unique (correo);
create index idx_vend_emp_tenant on vendedor_empresa (id_vendedor);
alter table vendedor_empresa add constraint uk_vend_emp unique (id_vendedor, id_empresa);
create index idx_venta_tenant on venta (id_vendedor);
create index idx_venta_cliente_cliente on venta_cliente (id_cliente);
alter table venta_cliente add constraint uk_venta_cliente unique (id_venta, id_cliente);
create index idx_venta_lote_lote on venta_lote (id_lote);
alter table venta_lote add constraint uk_venta_lote unique (id_venta, id_lote);
